-- rice-cozy — GENERATED by theme-palette. Edit themes/cozy/seed.sh instead.
-- IntelliJ-New-UI-flavored mapping over the cozy palette.
vim.cmd.highlight("clear")
vim.g.colors_name = "rice-cozy"
vim.o.termguicolors = true

local c = {
  bg = "#1e1e2e", bg_dark = "#181825", bg_hl = "#313244",
  fg = "#cdd6f4", muted = "#a6adc8", accent = "#cba6f7", alt = "#89b4fa",
  red = "#f38ba8", green = "#a6e3a1", yellow = "#f9e2af",
  blue = "#89b4fa", magenta = "#f5c2e7", cyan = "#94e2d5",
  kw = "#f49c9a", fn = "#96b9ee", str = "#74bc9e",
  num = "#73c5db", typ = "#e4bb99", const = "#c8a8e1",
  prop = "#c7c7f1", comment = "#76798c", op = "#aab1cd",
  special = "#89b4fa",
  border_a = "#7c6da3", border_i = "#28293a",
  black = "#45475a", bblack = "#585b70",
}

local hl = function(g, o) vim.api.nvim_set_hl(0, g, o) end

-- editor chrome: low-contrast separators, quiet gutters, accent only on focus
hl("Normal", { fg = c.fg, bg = c.bg })
hl("NormalFloat", { fg = c.fg, bg = c.bg_dark })
hl("FloatBorder", { fg = c.border_a, bg = c.bg_dark })
hl("FloatTitle", { fg = c.accent, bg = c.bg_dark, bold = true })
hl("WinSeparator", { fg = c.border_i })
hl("CursorLine", { bg = c.bg_hl })
hl("CursorLineNr", { fg = c.accent, bold = true })
hl("LineNr", { fg = c.bblack })
hl("SignColumn", { bg = c.bg })
hl("ColorColumn", { bg = c.bg_dark })
hl("Visual", { bg = c.black })
hl("Search", { fg = c.bg, bg = c.yellow })
hl("IncSearch", { fg = c.bg, bg = c.accent })
hl("CurSearch", { link = "IncSearch" })
hl("MatchParen", { fg = c.accent, bg = c.bg_hl, bold = true })
hl("Pmenu", { fg = c.fg, bg = c.bg_dark })
hl("PmenuSel", { bg = c.bg_hl, bold = true })
hl("PmenuSbar", { bg = c.bg_dark })
hl("PmenuThumb", { bg = c.border_a })
hl("StatusLine", { fg = c.fg, bg = c.bg_dark })
hl("StatusLineNC", { fg = c.muted, bg = c.bg_dark })
hl("TabLine", { fg = c.muted, bg = c.bg_dark })
hl("TabLineSel", { fg = c.bg, bg = c.accent, bold = true })
hl("TabLineFill", { bg = c.bg_dark })
hl("Folded", { fg = c.muted, bg = c.bg_dark, italic = true })
hl("FoldColumn", { fg = c.bblack })
hl("NonText", { fg = c.black })
hl("Whitespace", { fg = c.black })
hl("Directory", { fg = c.fn })
hl("Title", { fg = c.accent, bold = true })
hl("ErrorMsg", { fg = c.red })
hl("WarningMsg", { fg = c.yellow })
hl("MoreMsg", { fg = c.green })
hl("Question", { fg = c.accent })
hl("QuickFixLine", { bg = c.bg_hl })
hl("WildMenu", { link = "PmenuSel" })

-- syntax: warm keywords, cool calls, everything near one lightness
hl("Comment", { fg = c.comment, italic = true })
hl("String", { fg = c.str })
hl("Character", { fg = c.str })
hl("Number", { fg = c.num })
hl("Float", { fg = c.num })
hl("Boolean", { fg = c.const })
hl("Constant", { fg = c.const })
hl("Identifier", { fg = c.fg })
hl("Function", { fg = c.fn })
hl("Statement", { fg = c.kw })
hl("Keyword", { fg = c.kw })
hl("Conditional", { fg = c.kw })
hl("Repeat", { fg = c.kw })
hl("Label", { fg = c.kw })
hl("Exception", { fg = c.kw })
hl("Operator", { fg = c.op })
hl("Type", { fg = c.typ })
hl("StorageClass", { fg = c.kw })
hl("Structure", { fg = c.typ })
hl("Typedef", { fg = c.typ })
hl("PreProc", { fg = c.special })
hl("Include", { fg = c.kw })
hl("Define", { fg = c.special })
hl("Macro", { fg = c.special })
hl("Special", { fg = c.special })
hl("SpecialChar", { fg = c.special })
hl("Delimiter", { fg = c.op })
hl("Todo", { fg = c.bg, bg = c.yellow, bold = true })
hl("Error", { fg = c.red })

-- treesitter / semantic tokens
hl("@variable", { fg = c.fg })
hl("@variable.member", { fg = c.prop })
hl("@variable.parameter", { fg = c.fg, italic = true })
hl("@variable.builtin", { fg = c.const, italic = true })
hl("@property", { fg = c.prop })
hl("@field", { fg = c.prop })
hl("@function", { fg = c.fn })
hl("@function.method", { fg = c.fn })
hl("@function.builtin", { fg = c.fn })
hl("@function.macro", { fg = c.special })
hl("@constructor", { fg = c.typ })
hl("@keyword", { fg = c.kw })
hl("@keyword.function", { fg = c.kw })
hl("@keyword.return", { fg = c.kw })
hl("@keyword.operator", { fg = c.kw })
hl("@string", { fg = c.str })
hl("@string.escape", { fg = c.special })
hl("@string.regexp", { fg = c.special })
hl("@number", { fg = c.num })
hl("@boolean", { fg = c.const })
hl("@constant", { fg = c.const })
hl("@constant.builtin", { fg = c.const })
hl("@type", { fg = c.typ })
hl("@type.builtin", { fg = c.typ })
hl("@attribute", { fg = c.special })
hl("@punctuation.bracket", { fg = c.op })
hl("@punctuation.delimiter", { fg = c.op })
hl("@punctuation.special", { fg = c.special })
hl("@tag", { fg = c.kw })
hl("@tag.attribute", { fg = c.prop })
hl("@tag.delimiter", { fg = c.op })
hl("@comment", { link = "Comment" })
-- markdown / notes: one accent for headings (no rainbow), alt for links,
-- finished tasks and quotes fade back — tuned for the ~/notes vault
hl("@markup.heading", { fg = c.accent, bold = true })
hl("@markup.strong", { bold = true })
hl("@markup.italic", { italic = true })
hl("@markup.raw", { fg = c.str })
hl("@markup.link", { fg = c.alt, underline = true })
hl("@markup.link.label", { fg = c.alt })
hl("@markup.link.url", { fg = c.muted, underline = true })
hl("@markup.list", { fg = c.accent })
hl("@markup.list.checked", { fg = c.comment })
hl("@markup.list.unchecked", { fg = c.accent })
hl("@markup.quote", { fg = c.muted, italic = true })
for i = 1, 6 do
  hl(("RenderMarkdownH%dBg"):format(i), { bg = c.bg_dark })
end
hl("RenderMarkdownCode", { bg = c.bg_dark })
hl("RenderMarkdownBullet", { fg = c.accent })
hl("@lsp.type.property", { link = "@property" })
hl("@lsp.type.parameter", { link = "@variable.parameter" })

