hl("DiagnosticUnderlineWarn", { undercurl = true, sp = c.yellow })
hl("DiagnosticUnderlineInfo", { undercurl = true, sp = c.fn })
hl("DiagnosticUnderlineHint", { undercurl = true, sp = c.cyan })
